import sys
import time
import requests
from collections import deque

def parse_hostname(url):
    try:
        if '://' in url:
            scheme, rest = url.split('://', 1)
            if '/' in rest:
                hostname, *rest = rest.split('/', 1)
                return hostname
            else:
                return rest
        return url
    except:
        return url

def fetch_url(url, token):
    hostname = parse_hostname(url)
    headers = {'Authorization': f'Bearer {token}'}
    try:
        response = requests.get(url, headers=headers, timeout=5)
        return response.status_code, url
    except requests.exceptions.RequestException:
        return None, url

def main():
    if len(sys.argv) != 2:
        print("Usage: python fetch.py <path-to-urls-file>")
        return

    urls_file = sys.argv[1]
    try:
        with open(urls_file, 'r') as f:
            urls = [line.strip() for line in f if line.strip() and not line.strip().startswith('#')]
    except FileNotFoundError:
        print(f"Error: File {urls_file} not found.")
        return

    try:
        with open('tokens.txt', 'r') as f:
            tokens = {line.strip().split('\t') for line in f if line.strip()}
    except FileNotFoundError:
        print("Error: tokens.txt not found.")
        return

    hostname_tokens = {host: token for host, token in tokens}

    request_queue = deque()
    last_request_time = 0

    for url in urls:
        hostname = parse_hostname(url)
        if hostname not in hostname_tokens:
            print(f"DENIED {url}")
            continue

        token = hostname_tokens[hostname]
        request_queue.append((url, token))

        while len(request_queue) > 0:
            current_time = time.time()
            if current_time - last_request_time >= 2:
                break
            if len(request_queue) > 4:
                oldest_url, oldest_token = request_queue.popleft()
                continue

            url, token = request_queue.popleft()
            last_request_time = current_time

            status_code, result = fetch_url(url, token)
            if result is not None:
                print(f"{status_code} {result}")
            else:
                print(f"ERROR {result}")

if __name__ == "__main__":
    main()

import requests
import time
from urllib.parse import urlparse
from collections import deque

def fetch():
    urls = []
    with open('urls.txt', 'r') as f:
        for line in f:
            stripped = line.strip()
            if stripped and not stripped.startswith('#'):
                urls.append(stripped)

    tokens = {}
    with open('tokens.txt', 'r') as f:
        for line in f:
            parts = line.strip().split('\t')
            if len(parts) == 2:
                hostname, token = parts
                tokens[hostname] = token

    request_queue = deque(maxlen=3)
    start_time = time.time()

    for url in urls:
        parsed = urlparse(url)
        hostname = parsed.netloc
        if hostname not in tokens:
            print(f"DENIED {url}")
            continue

        token = tokens[hostname]
        headers = {'Authorization': f'Bearer {token}'}
        request_queue.append((url, time.time()))

        while len(request_queue) >= 3:
            oldest = request_queue[0]
            oldest_time = oldest[1]
            if time.time() - oldest_time >= 2:
                request_queue.popleft()

        try:
            response = requests.get(url, headers=headers, timeout=5)
            print(f"{response.status_code} {url}")
        except requests.exceptions.RequestException:
            print(f"ERROR {url}")

if __name__ == "__main__":
    fetch()

import requests
import time
import sys

def extract_hostname(url):
    try:
        return url.split('://')[1].split('/')[0].split(':')[0]
    except IndexError:
        return None

def main():
    urls = []
    with open('urls.txt', 'r') as f:
        urls = [line.strip() for line in f if line.strip()]

    tokens = {}
    with open('tokens.txt', 'r') as f:
        for line in f:
            parts = line.strip().split('\t')
            if len(parts) >= 2:
                tokens[parts[0]] = parts[1]

    for i, url in enumerate(urls):
        hostname = extract_hostname(url)
        if hostname is None:
            print("DENIED " + url)
            continue

        if hostname not in tokens:
            print("DENIED " + url)
            continue

