import requests
import time
from urllib.parse import urlparse

def fetch_urls():
    with open('urls.txt', 'r') as url_file:
        urls = [line.strip() for line in url_file if line.strip()]

    with open('tokens.txt', 'r') as token_file:
        tokens = {line.split('\t')[0]: line.split('\t')[1].strip() for line in token_file}

    for url in urls:
        parsed = urlparse(url)
        hostname = parsed.netloc
        if hostname not in tokens:
            print(f"DENIED {url}")
            continue

        token = tokens[hostname]
        headers = {'Authorization': f'Bearer {token}'}
        start_time = time.time()

        try:
            response = requests.get(url, headers=headers, timeout=5)
            print(f"{response.status_code} {url}")
        except requests.exceptions.RequestException:
            print(f"ERROR {url}")

        if url != urls[-1]:  # Wait only between URLs, not after the last one
            time.sleep(0.7)

if __name__ == "__main__":
    fetch_urls()
